import json
from pathlib import Path
root=Path(__file__).resolve().parent
p=json.loads((root/'plan.json').read_text());r=json.loads((root/'receipts.json').read_text())
url='https://simeoncalixte1990.atlassian.net/browse/'
def link(k):return f'[{k}]({url}{k})'
names={
'I':['Claims credibility','Fragmented claims experience','Underwriting priorities','Decision traceability','Extraction confidence','Change impact','Authority controls','Portfolio accumulation','Pricing governance','Coverage certainty','Post-bind amendments','Premium reconciliation','Delegated authority oversight','Reporting quality','Renewal preparation','Operational accountability','System integration','Management reporting','Operational resilience','Adoption economics'],
'B':['Client-centered navigation','Duplicate entry','Submission readiness','Market suitability','Functional discovery controls','Selective disclosure','Client confidentiality','Market approach tracking','Comparable quotations','Negotiation clarity','Placement completeness','Client presentation','Client approvals','Document delivery','Communication continuity','Commission accounting','Servicing continuity','Team handovers','Relationship protection','Commercial value'],
'R':['Submission depth','Data quality','Loss experience','Exposure reconciliation','Treaty specificity','Contract economics','Layer relationships','Reinstatements','Commission complexity','Wording differences','Model provenance','Portfolio accumulation','Scenario analysis','Capacity certainty','Counterparty assessment','Collateral visibility','Reporting obligations','Claims and recoveries','Retrocession traceability','Settlement and renewal evidence']}
lines=['# Persona feedback → Jira delivery map','', 'Date: 2026-11-04. Scope: create/reconcile user stories from all 60 insurer, broker and reinsurer criticisms, with explicit acceptance criteria and Definition of Done. Preserve document-driven LLM form generation and existing implementation obligations.','', 'Live Jira baseline: all 85 AIN issues refreshed, including descriptions, parents, statuses, links and subtasks. No baseline native subtasks were present. Current source and generated-form/catalog documentation were reviewed. Earlier findings are not assumed to be current missing behavior.','', '## Coverage','', 'Overlapping concerns share stories: 35 new stories, 2 reused stories (AIN-79/80), 1 new broker coordination epic, and 9 implementation subtasks where no existing task adequately owns the new workflow. All 60 feedback points are mapped below.','']
for prefix,label in [('I','Insurer'),('B','Broker'),('R','Reinsurer')]:
 lines += ['### '+label,'','| Feedback | Concern | Jira stories |','| --- | --- | --- |']
 for i,name in enumerate(names[prefix],1):
  k=f'{prefix}{i}';keys=[r['issues'].get(x,x) for x in p['coverage'][k]]
  lines.append(f'| {k} | {name} | '+', '.join(map(link,keys))+' |')
 lines.append('')
lines += ['## Stories, parents and implementation dependencies','','Relates links identify existing shared implementation ownership or completed reuse evidence. Blocks links order the new required predecessor outcomes. They do not turn every historical related issue into a dependency. Original tasks, parents and acceptance criteria are retained.','','| Story | Epic | Required implementation owners | Predecessor stories |','| --- | --- | --- | --- |']
for s in p['stories']:
 k=r['issues'][s['id']];e=r['issues']['broker-epic'] if s['epic']=='BROKER' else s['epic'];tasks=s['tasks'] or [r['issues'].get(s['id']+'-implementation','pending subtask')]
 lines.append('| '+link(k)+' '+s['title']+' | '+link(e)+' | '+', '.join(map(link,tasks))+' | '+(', '.join(link(r['issues'][d]) for d in s['depends']) or 'None')+' |')
lines += ['', '## Scope and exclusions','', '- AIN-1–10/12 and AIN-47 retain broader release, finance and data-model obligations. The new stories supplement them; no parent was closed or scope removed.', '- Completed AIN-33/34/52/61–78/81–85 are reusable capabilities/evidence, not new implementation claims. AIN-70/71/72 remain Done and are not reopened for unrelated client coordination.', '- AIN-79/80 are reused and clarified rather than duplicated. AIN-30/31/32/35/36/37/38/39/40 retain domain financial implementation ownership.', '- AIN-11 and AIN-41–44 subscription/checkout/metering work remains a release dependency where AIN-12 requires it, but is not duplicated as persona feedback work: none of the 60 points requests a new subscription workflow.', '- Unrelated social feature expansion (messaging/uploads/public indexing), a second identity system, a second ledger, hard-coded forms for every risk class and automatic public appetite disclosure are excluded. They are not required to resolve this feedback.', '', '## LLM-generated forms','',p['form_dod'],'', 'Generation produces a review candidate with evidence, semantic/entity bindings and pinned versions. Deterministic validation, human correction/reconciliation and explicit activation govern downstream use. New forms do not replace existing workflow scaffolding or service ownership. See EnsuredPipelineSchemaGeneration/README.md, EnsuredAPI/src/formCatalog/README.md and docs/submission-variability-plan/04-schema-generation.md.','', '## Definition of Done','']
lines += [f'{i+1}. {v}' for i,v in enumerate(p['dod'])]
lines += ['', 'Each Jira story also contains outcome-specific acceptance criteria and a concrete verification scenario; the common gate is not a substitute for those criteria.', '', '## Verification and release status','', '- Planning verification: source review, current Jira reconciliation, acyclic predecessor graph and complete 60-point coverage check. Jira creation/update descriptions and parents are read back; final verification checks story types, statuses, implementation links, dependency direction and subtasks.', '- Application implementation, new Storybook/API tests, provider tests, migrations and deployment: **not performed**. New issues remain To Do. Existing statuses are preserved.', '- Story execution evidence is explicitly pending; no test IDs/results or staged build IDs are fabricated. Future delivery must record ticket → component → executable Storybook story → command/result mapping.', '- Existing fixture/live paths to extend include EnsuredMarketplace/src/Participation.stories.tsx, EnsuredMarketplace/src/Marketplace.stories.tsx, EnsuredNetwork/frontend/src/{Fixtures,PartyParticipation,Participation.live}.stories.tsx, EnsuredNetwork/test/participation-live.mjs, EnsuredUI/src/Pages/InsurerDashboard/sections/*.stories.tsx and commercial/claims host workflows. Fixture and real-service evidence remain separate.', '- Original broader platform objective remains incomplete. This request is backlog creation only; next implementation step is to select the dependency-ready story and refresh its current Jira/source evidence.','', '## Artifacts','', '- `plan.json`: complete story content, criteria, DoD and feedback mapping.', '- `baseline.json`: live pre-change Jira snapshot.', '- `receipts.json`: created IDs, updates, links and read-back evidence.', '- `build_plan.py`, `publish.py`, `write_map.py`: reproducible planning/publishing helpers; credentials are not stored in these artifacts. Publishing depends on the temporary environment-specific API helper and must not be blindly replayed.','']
(root/'COVERAGE.md').write_text('\n'.join(lines))
(root/'feedback-register.json').write_text(json.dumps({f'{prefix}{i}':{'concern':name,'stories':[r['issues'].get(x,x) for x in p['coverage'][f'{prefix}{i}']]} for prefix in names for i,name in enumerate(names[prefix],1)},indent=2)+'\n')
print('Wrote coverage and delivery map')
